def handle_error(error: Exception) -> JSONResponse:
    return JSONResponse(
        status_code=500,
        content={
            "error": str(error),
            "traceback": traceback.format_exc(),  # Exposes internals
            "path": str(Path(__file__).parent)       # Exposes file system
        }
    )
